"""Original calcium/parathyroid/bone chapter: diagnosis and risk stratification."""
from qbank_authoring import question,ref,finalize
PT=ref('Fifth International Workshop: Primary Hyperparathyroidism, 2022','https://doi.org/10.1002/jbmr.4677')
HP=ref('ESE Revised Chronic Hypoparathyroidism Guideline, 2025','https://academic.oup.com/ejendo/article/193/5/G83/8321487')
OS=ref('NOGG: Clinical Guideline for Osteoporosis, 2024','https://www.nogg.org.uk/sites/nogg/download/NOGG-Guideline-2024.pdf')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Repeated hypercalcemia is accompanied by PTH in the upper part of the laboratory reference range. What is the key interpretation?', 'PTH is inappropriately nonsuppressed and supports a PTH-dependent mechanism',[
 ('A reference-range PTH automatically excludes primary hyperparathyroidism','Normal regulation should suppress PTH during hypercalcemia.'),('The result proves malignancy-associated PTHrP excess','PTH would usually be suppressed.'),('A parathyroid scan is needed before interpreting the hormones','The biochemical diagnosis comes before localization.')],
 'Normality depends on the feedback context', '**A PTH value can be inappropriate despite lying within the printed interval.**',['Confirm genuine hypercalcemia and persistence.','FHH, drugs and other PTH-dependent states remain in the differential.'], '**Assess kidney, skeletal and family features.**',['Do not diagnose a specific gland from serum values alone.','Use imaging for a later surgical-localization question.'],[['High calcium','Should suppress PTH'],['Nonsuppressed PTH','PTH-dependent pathway'],['Next assessment','Cause and organ consequences']],[PT])
q('Mild lifelong hypercalcemia affects several relatives. PTH is nonsuppressed and the calcium-clearance ratio is below 0.01, without major confounders. Which diagnosis is favored?', 'Familial hypocalciuric hypercalcemia',[
 ('All low clearance ratios prove primary hyperparathyroidism','FHH is an important alternative.'),('Malignancy-associated hypercalcemia as the best fit','The lifelong familial and PTH pattern is different.'),('Parathyroidectomy is routinely curative for FHH','The altered calcium-sensing set point persists.')],
 'A calcium-sensing phenotype can mimic primary gland disease', '**FHH commonly involves CASR-related altered calcium sensing.**',['GNA11 and AP2S1 are other recognized causes.','CKD, thiazides and vitamin D deficiency can lower urinary calcium and create overlap.'], '**Confirm the phenotype and consider genetic testing when indicated.**',['Avoid unnecessary parathyroid surgery.','Do not use the ratio as an absolute standalone discriminator.'],[['Course','Often lifelong mild hypercalcemia'],['Urine','Relative hypocalciuria'],['Management implication','Surgery usually not indicated']],[PT],'clinical_scenario')
q('PTH remains high with repeatedly normal total and ionized calcium. What is required before diagnosing normocalcemic primary hyperparathyroidism?', 'Exclude secondary causes such as vitamin D deficiency, CKD, low calcium intake, malabsorption and relevant medications',[
 ('One high PTH result is sufficient','Persistence and exclusions are necessary.'),('Normal calcium proves there is no parathyroid disorder','A normocalcemic phenotype exists after careful exclusion.'),('A positive sestamibi scan replaces biochemical assessment','Localization is not diagnostic proof.')],
 'Normocalcemic primary disease is a diagnosis of exclusion', '**Secondary stimulation can raise PTH while maintaining calcium.**',['Both total and ionized calcium require appropriate measurement.','The definition requires repeated findings over time.'], '**Correct reversible causes before assigning the label.**',['Drug effects and dietary calcium deserve review.','Management evidence is less definitive than for classic hypercalcemic disease.'],[['Pattern','Normal calcium/high PTH'],['First step','Exclude secondary stimulation'],['Diagnosis','Persistent integrated phenotype']],[PT])
q('A 44-year-old has biochemically confirmed asymptomatic primary hyperparathyroidism without other surgical criteria. Which factor supports surgery under the Fifth Workshop?', 'Age below 50 years',[
 ('Absence of symptoms means surgery can never be offered','Age is an independent guideline indication.'),('A normal ultrasound excludes the surgical option','Localization failure does not negate the biochemical disease.'),('Surgery is indicated only if calcium exceeds 14 mg/dL','The criteria include age, skeletal and renal findings and a lower calcium excess threshold.')],
 'Asymptomatic does not mean there is no treatment indication', '**Age below 50 is a Workshop criterion.**',['Other criteria include calcium more than 1 mg/dL above the upper limit and specified organ involvement.','Shared decisions also account for operative suitability and preference.'], '**Refer to an experienced parathyroid team.**',['Complete skeletal and renal assessment.','Explain that imaging plans the operation rather than decides whether the disease exists.'],[['Age','Below 50 supports surgery'],['Symptoms','Not required for all indications'],['Planning','Biochemical diagnosis before localization']],[PT],'clinical_scenario')
q('Which renal finding is a surgical indication in otherwise asymptomatic primary hyperparathyroidism under the Fifth Workshop?', 'Creatinine clearance below 60 mL/min or documented nephrolithiasis/nephrocalcinosis',[
 ('Any urine calcium value above zero','A specific threshold and clinical context are needed.'),('A normal eGFR excludes all renal surgical criteria','Stones and sex-specific hypercalciuria can independently qualify.'),('Only dialysis dependence counts as renal involvement','The guideline intervenes before that severity.')],
 'Renal criteria include function, stones and calcium excretion', '**Hypercalciuria above 250 mg/day in women or 300 mg/day in men is also a criterion.**',['A 24-hour collection is interpreted for completeness and confounders.','Imaging can reveal silent stones.'], '**Assess all qualifying domains.**',['Bone findings and calcium severity can provide additional indications.','Avoid waiting for irreversible advanced complications.'],[['Function','Clearance below 60'],['Structure','Stones/nephrocalcinosis'],['Urine calcium','Above 250 women/300 men mg/day']],[PT])
q('Primary hyperparathyroidism is established and surgery is planned. What is the purpose of neck ultrasound or sestamibi localization?', 'Planning the operative approach rather than establishing the biochemical diagnosis',[
 ('A negative localization scan excludes the disease','Nonlocalizing disease can still be surgically treated.'),('A positive scan proves the only possible cause of hypercalcemia','Imaging must be interpreted after the hormonal diagnosis.'),('Every patient requires an identical combination regardless of context','Localization strategy depends on local expertise and prior surgery.')],
 'Diagnosis and localization are separate tasks', '**Imaging can guide focused surgery when appropriate.**',['Multigland disease can be harder to localize.','Experienced surgical assessment remains important when imaging is negative or discordant.'], '**Avoid imaging-driven overdiagnosis.**',['Do not substitute a gland image for PTH-calcium interpretation.','Discuss the potential need for broader exploration.'],[['Biochemistry','Establishes disease'],['Localization','Guides surgery'],['Negative scan','Does not erase diagnosis']],[PT])
q('A patient with primary hyperparathyroidism cannot undergo surgery and has both hypercalcemia and low bone density. Which distinction helps select medication?', 'Cinacalcet primarily lowers calcium, while antiresorptive therapy primarily addresses bone density',[
 ('Both strategies have identical effects on calcium and bone in every patient','Their major actions differ.'),('Cinacalcet reliably replaces all skeletal treatment','Bone-directed benefit is not equivalent.'),('Antiresorptives cure the autonomous parathyroid source','They do not remove the gland mechanism.')],
 'Medical treatment can target consequences without curing the source', '**Cinacalcet increases calcium-sensing receptor sensitivity and lowers calcium.**',['Bisphosphonates or denosumab can improve BMD in appropriate patients.','Combination treatment can be considered when both goals matter.'], '**Monitor the chosen endpoints and safety.**',['Continue calcium, kidney and skeletal surveillance.','Revisit surgical eligibility if circumstances change.'],[['Cinacalcet','Calcium control'],['Antiresorptive','Bone protection'],['Surgery','Definitive source treatment when suitable']],[PT])
q('Primary hyperparathyroidism is managed without surgery. What is a key monitoring principle?', 'Follow calcium, kidney function and skeletal status, and reconsider surgery if guideline triggers emerge',[
 ('No follow-up is needed after choosing observation','Disease consequences can evolve.'),('Restrict all calcium severely regardless of intake','Inadequate intake can worsen secondary PTH stimulation and bone health.'),('Repeated localization scans are the main monitoring endpoint','Organ and biochemical status are more relevant.')],
 'Observation is an active management plan', '**Maintain appropriate calcium and vitamin D rather than indiscriminate restriction.**',['Monitoring frequency follows severity and guideline recommendations.','New stones, fracture or worsening renal function can alter the decision.'], '**Explain symptoms and thresholds for reassessment.**',['Use comparable DXA methods when following BMD.','Review drugs and dehydration that can aggravate calcium.'],[['Monitoring','Calcium, kidney and bone'],['Nutrition','Appropriate calcium/vitamin D'],['Change','Reassess surgery']],[PT])
q('Marked prolonged hypocalcemia with low phosphate develops after parathyroidectomy for severe high-turnover bone disease. What is the likely mechanism?', 'Hungry bone syndrome with rapid skeletal mineral uptake',[
 ('Permanent low PTH is the only explanation for every postoperative low calcium','Hungry bone is a distinct mechanism, often with low phosphate and high prior turnover.'),('New autonomous calcium release from bone','Calcium is moving into bone.'),('The operation necessarily failed to remove hormone excess','This can follow effective surgery.')],
 'A remodeled skeleton can abruptly switch to net mineral uptake', '**Calcium, phosphate and magnesium can be drawn into bone.**',['Severe preoperative disease and high bone turnover increase risk.','PTH and the complete biochemical pattern help distinguish mechanisms.'], '**Use close monitoring and substantial replacement when needed.**',['Calcium and active vitamin D requirements can be prolonged.','Correct magnesium and monitor cardiac/neuromuscular symptoms.'],[['Mechanism','Bone remineralization'],['Pattern','Low calcium, often low phosphate'],['Care','Monitored calcium/active vitamin D and magnesium']],[PT,HP],'clinical_scenario')
q('Chronic hypocalcemia occurs with inappropriately low PTH after neck surgery. What is the usual conventional long-term treatment?', 'Activated vitamin D with adequate calcium intake and individualized supplementation',[
 ('Routine cinacalcet to suppress PTH further','This can worsen hypocalcemia.'),('A phosphate supplement for every patient regardless of level','Phosphate is often high in hypoparathyroidism.'),('Large doses without urinary or renal monitoring','Treatment can cause hypercalciuria and renal complications.')],
 'Conventional therapy bypasses some consequences of missing PTH', '**Active vitamin D promotes calcium absorption.**',['The goal is symptom control with calcium in an appropriate low-normal or slightly low range rather than maximal normalization.','Renal calcium conservation remains impaired without PTH.'], '**Monitor serum and urinary calcium and kidney function.**',['Check magnesium and phosphate.','Avoid overtreatment that trades symptoms for nephrocalcinosis.'],[['Missing hormone','PTH'],['Conventional treatment','Active vitamin D plus calcium as needed'],['Safety','Renal and urinary-calcium monitoring']],[HP])
q('Why can a patient with treated hypoparathyroidism develop hypercalciuria despite a low-normal serum calcium?', 'Calcium and active vitamin D do not fully replace PTH-mediated renal calcium conservation',[
 ('Normal serum calcium guarantees normal urine calcium','The two can diverge.'),('PTH deficiency always prevents urinary calcium loss','PTH normally promotes renal retention.'),('Urine testing has no role during long-term therapy','It is important for renal safety.')],
 'Serum control does not ensure physiological renal handling', '**Conventional therapy can increase absorbed calcium without restoring distal tubular PTH action.**',['High urinary calcium contributes to stones and nephrocalcinosis.','Sodium intake and selected thiazide use can influence excretion.'], '**Individualize the replacement strategy.**',['Monitor blood pressure and electrolytes if adding a thiazide.','Consider PTH replacement when conventional treatment remains inadequate.'],[['Serum calcium','May look acceptable'],['Urine calcium','Can remain excessive'],['Underlying gap','Absent renal PTH action']],[HP])
q('Symptoms and biochemical control remain unsatisfactory in chronic hypoparathyroidism despite optimized calcium and activated vitamin D. Which option is supported by the revised 2025 ESE guideline?', 'Consider PTH replacement therapy in an eligible patient',[
 ('Continue escalating conventional tablets indefinitely without reviewing harm','Pill burden, hypercalciuria and renal effects can limit that strategy.'),('PTH therapy is never an option in adults','Approved replacement options now exist.'),('Stop all calcium-regulating therapy abruptly','This risks severe hypocalcemia.')],
 'Replacement can address physiology beyond intestinal calcium loading', '**PTH therapy can reduce conventional pill burden and improve biochemical handling.**',['Eligibility and product availability depend on jurisdiction.','Transition requires a monitored calcium and active-vitamin-D adjustment plan.'], '**Define the goals and monitor closely.**',['Symptoms, kidney safety and quality of life matter.','Do not assume therapy eliminates all follow-up or injection-related burden.'],[['Reason to consider','Inadequate optimized conventional control'],['Option','PTH replacement'],['Transition','Specialist monitored adjustment']],[HP])
q('Hypocalcemia and hyperphosphatemia occur with elevated PTH and a phenotype of shortened metacarpals. Which mechanism is most likely?', 'PTH resistance',[
 ('Simple isolated PTH deficiency','PTH is elevated rather than deficient.'),('Primary hyperparathyroidism','That usually raises calcium.'),('FHH as the explanation','That is a hypercalcemic phenotype.')],
 'A target-organ defect can produce compensatory hormone excess', '**Pseudohypoparathyroid disorders involve impaired PTH signaling.**',['Phenotype and other hormone resistances vary by molecular subtype.','Not every case has the classic skeletal features.'], '**Use biochemical and genetic assessment.**',['Treat calcium-phosphate abnormalities and assess associated endocrine issues.','Do not interpret high PTH without considering calcium and kidney context.'],[['Calcium','Low'],['Phosphate','High'],['PTH','Elevated due to resistance']],[HP],'clinical_scenario')
q('Hypercalcemia follows excessive vitamin D supplement use. PTH is suppressed and 25-hydroxyvitamin D is markedly elevated. Which mechanism is favored?', 'Vitamin D intoxication',[
 ('Primary hyperparathyroidism','PTH is suppressed.'),('Isolated calcitriol excess from granulomatous disease as the best specified pattern','That is more directly associated with excess 1,25-dihydroxyvitamin D rather than the described supplement-driven 25-hydroxy pattern.'),('Untreated hypoparathyroidism','That ordinarily causes low calcium.')],
 'The vitamin D metabolite pattern helps identify the source', '**Excess intake can increase calcium absorption and cause hypercalcemia and hypercalciuria.**',['The effect can persist because vitamin D is stored in tissue.','Multiple products can create an unrecognized combined dose.'], '**Stop the exposure and treat severity.**',['Assess renal function, volume and calcium serially.','Avoid assuming all over-the-counter vitamin doses are harmless.'],[['PTH','Suppressed'],['25-hydroxyvitamin D','Markedly high'],['Exposure','Excess supplementation']],[PT],'clinical_scenario')
q('A postmenopausal woman has femoral-neck T-score −2.7. What does this densitometric result indicate?', 'Osteoporosis by the standard T-score criterion',[
 ('Osteopenia only','The osteoporosis threshold is at most −2.5.'),('Normal density because only the spine counts','Hip sites are valid diagnostic sites.'),('The T-score identifies the cause of bone loss','It measures relative density, not etiology.')],
 'Use the correct reference metric for the population', '**T-scores compare density with a young-adult reference.**',['In younger adults, Z-scores are generally preferred for reporting context.','A fragility fracture can establish high risk even without this T-score.'], '**Assess fracture risk and secondary causes.**',['The result informs treatment but is not the entire decision.','Check scan quality and artifacts.'],[['T-score at most −2.5','Osteoporosis'],['T-score between −1 and −2.5','Low bone mass'],['Evaluation','Risk and cause assessment']],[OS],'clinical_scenario')
q('An older adult sustains a low-trauma hip fracture but DXA T-score is −1.8. What is the key management principle?', 'The fragility fracture confers high risk and can warrant osteoporosis treatment despite a nonosteoporotic T-score',[
 ('Treatment must wait until T-score falls below −2.5','A major fragility fracture itself is an important indication.'),('A T-score above −2.5 proves the fracture was unrelated to bone fragility','Fracture risk is not determined by BMD alone.'),('Fall assessment is unnecessary once medication starts','Falls and rehabilitation remain central.')],
 'A fracture is a clinical event, not just a scan category', '**Prior major fragility fracture strongly predicts future fracture.**',['Recent fractures create particularly high near-term risk.','Secondary disease and falls can compound risk.'], '**Start a coordinated secondary-prevention plan.**',['Select treatment, calcium/vitamin D adequacy and rehabilitation appropriately.','Use a fracture liaison pathway when available.'],[['BMD','One risk component'],['Hip fragility fracture','Major clinical risk'],['Care','Medication plus falls and rehabilitation']],[OS],'clinical_scenario')
q('Why can standard FRAX underestimate fracture risk in a person with type 2 diabetes?', 'Diabetes-related skeletal quality and fall risks are not fully represented by the basic calculation',[
 ('Type 2 diabetes guarantees low fracture risk whenever BMD is normal','Fractures can occur despite relatively preserved BMD.'),('FRAX directly measures all bone microarchitecture','It is a clinical probability model.'),('No adjustment or clinical judgment is ever needed','Risk modifiers require interpretation.')],
 'Normal or high density does not always mean normal strength', '**Diabetes can impair bone material properties and increase falls.**',['Neuropathy, vision and hypoglycemia affect fall risk.','The effect varies with duration, complications and therapy.'], '**Use the locally recommended adjustment or specialist judgment.**',['Do not apply several adjustments blindly at once.','Assess fracture history and mobility directly.'],[['BMD','May be relatively preserved'],['Uncaptured factors','Quality and falls'],['Response','Contextual risk interpretation']],[OS])
q('A relatively young adult has osteoporosis and recurrent fractures. What is the best evaluation principle?', 'Investigate secondary causes rather than assuming ordinary age-related bone loss',[
 ('DXA alone identifies every cause','Endocrine, nutritional, hematological and drug causes need separate assessment.'),('Only calcium should be measured','A broader context-directed work-up is usually needed.'),('All secondary causes require the same treatment','The mechanism changes management.')],
 'The phenotype should fit the presumed diagnosis', '**Glucocorticoids, hypogonadism, malabsorption, hyperparathyroidism and plasma-cell disease are examples.**',['History and examination guide laboratory selection.','Low phosphate or abnormal ALP can suggest mineralization disorders.'], '**Treat the driver alongside fracture prevention.**',['Do not give antiresorptives reflexively before checking major correctable abnormalities.','Review all medicines and nutritional exposures.'],[['Question','Why is bone fragile?'],['Assessment','History plus targeted tests'],['Treatment','Cause-specific and fracture prevention']],[OS],'clinical_scenario')
q('Diffuse bone pain, proximal weakness, low phosphate and raised ALP suggest which process rather than uncomplicated osteoporosis?', 'Osteomalacia from impaired mineralization',[
 ('Pure low bone mass with normal mineralization as the complete explanation','The biochemical and symptomatic pattern suggests a mineralization defect.'),('FHH','That produces a different calcium phenotype.'),('An isolated thyroid-binding protein change','This does not explain the bone pattern.')],
 'Density can be low in more than one kind of bone disease', '**Osteomalacia can result from vitamin D deficiency or phosphate disorders.**',['Calcium and PTH vary with the mechanism.','Pseudofractures may be present.'], '**Identify and correct the mineralization problem.**',['A low DXA alone should not trigger an unexamined osteoporosis label.','Assess renal phosphate handling and vitamin D where indicated.'],[['Osteoporosis','Reduced amount with normally mineralized matrix'],['Osteomalacia','Defective mineralization'],['Clues','Pain, weakness and biochemical abnormalities']],[OS],'clinical_scenario')
q('An older adult has focal bone enlargement, hearing symptoms and high ALP with otherwise relatively normal calcium and phosphate. Which disorder is suggestive?', 'Paget disease of bone',[
 ('Diffuse vitamin D deficiency is proven by ALP alone','The focal deforming pattern suggests a different process.'),('Hypoparathyroidism','That is a calcium-regulation disorder rather than this focal remodeling phenotype.'),('Every high ALP must come from liver disease','Bone is another source and should be confirmed in context.')],
 'Focal excessive remodeling produces structurally abnormal bone', '**Bone pain, deformity and characteristic imaging support Paget disease.**',['Confirm the ALP source and disease extent.','An incidental biochemical abnormality does not automatically mean treatment is required.'], '**Treat symptomatic active disease and specific risks according to guidance.**',['Potent bisphosphonate therapy is often used when indicated.','Assess hearing, joint and neurological complications.'],[['Pattern','Focal remodeling'],['ALP','Often raised'],['Diagnosis','Clinical and characteristic imaging']],[OS],'clinical_scenario')
